#!/usr/bin/env node
'use strict';

const fs = require('fs');

function main() {
  const file = process.argv[2];
  if (!file) {
    console.error('usage: node extract.js <elf-binary>');
    process.exit(1);
  }
  const buf = fs.readFileSync(file);
  if (buf.length < 52 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('not an ELF file');
  }

  const is64 = buf[4] === 2;
  const le = buf[5] === 1;

  const u16 = (o) => (le ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = (o) => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const u64 = (o) => {
    const v = le ? buf.readBigUInt64LE(o) : buf.readBigUInt64BE(o);
    return Number(v);
  };

  let phoff, phentsize, phnum;
  if (is64) {
    phoff = u64(32);
    phentsize = u16(54);
    phnum = u16(56);
  } else {
    phoff = u32(28);
    phentsize = u16(42);
    phnum = u16(44);
  }

  const out = {};
  for (let i = 0; i < phnum; i++) {
    const ph = phoff + i * phentsize;
    if (ph + phentsize > buf.length) break;
    const pType = u32(ph);
    if (pType !== 1) continue; // PT_LOAD only

    let pOffset, pVaddr, pFilesz;
    if (is64) {
      pOffset = u64(ph + 8);
      pVaddr = u64(ph + 16);
      pFilesz = u64(ph + 32);
    } else {
      pOffset = u32(ph + 4);
      pVaddr = u32(ph + 8);
      pFilesz = u32(ph + 16);
    }

    const end = Math.min(pOffset + pFilesz, buf.length);
    for (let off = pOffset; off + 4 <= end; off += 4) {
      const addr = pVaddr + (off - pOffset);
      out[addr] = le ? buf.readUInt32LE(off) : buf.readUInt32BE(off);
    }
  }

  process.stdout.write(JSON.stringify(out));
}

main();
